#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_p0x;
uniform float amzp_p0y;
uniform float amzp_p1x;
uniform float amzp_p1y;
uniform float amzp_p2x;
uniform float amzp_p2y;
uniform float amzp_p3x;
uniform float amzp_p3y;
uniform float amzp_p4x;
uniform float amzp_p4y;
uniform float amzp_p5x;
uniform float amzp_p5y;
uniform float amzp_p6x;
uniform float amzp_p6y;
uniform float amzp_p7x;
uniform float amzp_p7y;
uniform float amzp_p8x;
uniform float amzp_p8y;


    float cross2(float2 a,float2 b){return a.x*b.y-a.y*b.x;}
    bool root(float v,float2 q,float2 b,float2 c,float2 d,out float2 uv){
      float2 e=b+v*d;float denom=dot(e,e);if(denom<0.00000001)return false;
      float u=dot(q-v*c,e)/denom;uv=float2(u,v);
      return u>=-0.00001&&u<=1.00001&&v>=-0.00001&&v<=1.00001;
    }
    bool inverseCell(float2 p,float2 a,float2 ab,float2 corner,float2 ad,out float2 uv){
      float2 b=ab-a,c=ad-a,d=a-ab+corner-ad,q=p-a;
      float aa=-cross2(c,d),bb=cross2(q,d)-cross2(c,b),cc=cross2(q,b);
      if(abs(aa)<0.000001){if(abs(bb)<0.00000001)return false;return root(-cc/bb,q,b,c,d,uv);}
      float disc=bb*bb-4.0*aa*cc;if(disc<0.0)return false;float s=sqrt(disc);

      float stable=-0.5*(bb+(bb>=0.0?s:-s));
      if(abs(stable)>0.00000001&&root(cc/stable,q,b,c,d,uv))return true;
      return root(stable/aa,q,b,c,d,uv);
    }
    bool sourceUV(float2 p,out float2 source){
      float2 uv;
      if(inverseCell(p,float2(amzp_p0x,amzp_p0y),float2(amzp_p1x,amzp_p1y),float2(amzp_p4x,amzp_p4y),float2(amzp_p3x,amzp_p3y),uv)){source=(uv+float2(0.0,0.0))*0.5;return true;}
      if(inverseCell(p,float2(amzp_p1x,amzp_p1y),float2(amzp_p2x,amzp_p2y),float2(amzp_p5x,amzp_p5y),float2(amzp_p4x,amzp_p4y),uv)){source=(uv+float2(1.0,0.0))*0.5;return true;}
      if(inverseCell(p,float2(amzp_p3x,amzp_p3y),float2(amzp_p4x,amzp_p4y),float2(amzp_p7x,amzp_p7y),float2(amzp_p6x,amzp_p6y),uv)){source=(uv+float2(0.0,1.0))*0.5;return true;}
      if(inverseCell(p,float2(amzp_p4x,amzp_p4y),float2(amzp_p5x,amzp_p5y),float2(amzp_p8x,amzp_p8y),float2(amzp_p7x,amzp_p7y),uv)){source=(uv+float2(1.0,1.0))*0.5;return true;}
      return false;
    }
    void amzRender(){
      float2 destination=amzLayerNorm();
      if(false){float3 p=labPlaneInverse*float3(amzScreenNorm(),1.0);if(p.z<=0.000001){amzOutput=float4(0.0);return;}destination=p.xy/p.z;}
      float2 source;
      if(!sourceUV(destination,source)){amzOutput=float4(0.0);return;}
      if(false)amzOutput=amzTexture(0,source);
      else amzOutput=amzTexture(0,(float4(source,0.0,1.0)*amzLayerToScreen()).xy);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

